-- 055_trx.sql
-- Suspension straps (TRX): 17 exercises in the library, in English, French
-- and German, and two programs (beginner and intermediate) in the three
-- languages. The app files them on a TRX shelf, offers "TRX straps" in the
-- equipment of the sign-up and of the timed sessions.
--
-- Deploy: apply this file first, then the code (the app would otherwise add
-- the exercises as the athlete's own the first time).
--
-- Safe to re-run. All-or-nothing: wrapped in one transaction.

BEGIN;

INSERT INTO exercises (user_id, name, muscle_group, equipment, is_custom, description, name_fr, name_de, description_fr, description_de)
SELECT NULL, v.name, v.muscle_group, v.equipment, false, v.description, v.name_fr, v.name_de, v.description_fr, v.description_de
FROM (VALUES
  ('TRX Row', 'back', 'suspension', 'Facing the anchor, hold the handles and lean back, arms straight and body in a line. Pull the chest to the hands, lower slowly. Walk the feet forward to make it harder.', 'Tirage TRX', 'TRX-Rudern', 'Face à l''ancrage, poignées en main, se pencher en arrière bras tendus, corps gainé. Tirer la poitrine vers les mains, redescendre lentement. Avancer les pieds pour corser.', 'Zum Ankerpunkt gewandt, Griffe fassen und mit gestreckten Armen zurücklehnen, Körper gerade. Brust zu den Händen ziehen, langsam ablassen. Füße nach vorn setzen macht es schwerer.'),
  ('TRX Chest Press', 'chest', 'suspension', 'Facing away from the anchor, lean forward on the handles, arms straight. Lower the chest between the hands, push back up. Step back to make it easier.', 'Développé pectoraux TRX', 'TRX-Brustpresse', 'Dos à l''ancrage, en appui sur les poignées bras tendus, corps penché. Descendre la poitrine entre les mains, repousser. Reculer les pieds pour faciliter.', 'Vom Ankerpunkt abgewandt, mit gestreckten Armen auf die Griffe lehnen. Brust zwischen die Hände senken, wieder hochdrücken. Füße zurücksetzen macht es leichter.'),
  ('TRX Squat', 'legs', 'suspension', 'Facing the anchor, hold the handles with straight arms. Sit back into a deep squat, chest up, and stand up, the straps only for balance.', 'Squat TRX', 'TRX-Kniebeuge', 'Face à l''ancrage, poignées en main bras tendus. Descendre en squat profond, buste droit, et remonter : les sangles servent juste à l''équilibre.', 'Zum Ankerpunkt gewandt, Griffe mit gestreckten Armen halten. Tief in die Kniebeuge setzen, Brust aufrecht, wieder aufstehen – die Bänder nur zur Balance.'),
  ('TRX Suspended Lunge', 'legs', 'suspension', 'Facing away, one foot in the cradles behind you. Bend the front leg to lower the back knee, push back up through the front heel. Switch legs halfway.', 'Fente pied suspendu TRX', 'TRX-Ausfallschritt', 'Dos à l''ancrage, un pied dans les sangles derrière soi. Fléchir la jambe avant pour descendre le genou arrière, remonter en poussant sur le talon avant. Changer de jambe à mi-temps.', 'Vom Ankerpunkt abgewandt, ein Fuß hinten in den Schlaufen. Vorderes Bein beugen, bis das hintere Knie sinkt, über die vordere Ferse hochdrücken. Zur Hälfte Bein wechseln.'),
  ('TRX Hamstring Curl', 'legs', 'suspension', 'On your back, heels in the cradles. Lift the hips, pull the heels to the glutes, then extend the legs slowly, hips up.', 'Leg curl TRX', 'TRX-Beinbeuger', 'Sur le dos, talons dans les sangles. Monter les hanches, ramener les talons vers les fessiers, puis tendre les jambes lentement en gardant les hanches hautes.', 'Auf dem Rücken, Fersen in den Schlaufen. Hüfte heben, Fersen zum Gesäß ziehen, dann die Beine langsam strecken, Hüfte oben.'),
  ('TRX Pike', 'core', 'suspension', 'In a high plank, feet in the cradles. Lift the hips high with straight legs, then lower back to the plank without sagging.', 'Pike TRX', 'TRX-Pike', 'En planche bras tendus, pieds dans les sangles. Monter les hanches très haut jambes tendues, puis revenir en planche sans creuser le dos.', 'Im hohen Stütz, Füße in den Schlaufen. Hüfte mit gestreckten Beinen hoch anheben, dann zurück in den Stütz, ohne durchzuhängen.'),
  ('TRX Knee Tuck', 'core', 'suspension', 'In a high plank, feet in the cradles. Pull both knees to the chest, then extend back to the plank.', 'Genoux-poitrine TRX', 'TRX-Knieanzug', 'En planche bras tendus, pieds dans les sangles. Ramener les deux genoux vers la poitrine, puis revenir en planche.', 'Im hohen Stütz, Füße in den Schlaufen. Beide Knie zur Brust ziehen, dann zurück in den Stütz.'),
  ('TRX Mountain Climber', 'core', 'suspension', 'In a high plank, feet in the cradles. Drive the knees to the chest one after the other, fast, hips low.', 'Mountain climber TRX', 'TRX-Mountain-Climber', 'En planche bras tendus, pieds dans les sangles. Ramener les genoux vers la poitrine l''un après l''autre, vite, hanches basses.', 'Im hohen Stütz, Füße in den Schlaufen. Knie abwechselnd schnell zur Brust ziehen, Hüfte tief.'),
  ('TRX Plank', 'core', 'suspension', 'Forearms on the floor, feet in the cradles, body in a straight line. Hold without letting the hips drop.', 'Gainage pieds suspendus TRX', 'TRX-Unterarmstütz', 'Avant-bras au sol, pieds dans les sangles, corps aligné. Tenir sans laisser tomber les hanches.', 'Unterarme am Boden, Füße in den Schlaufen, Körper in einer Linie. Halten, ohne die Hüfte sinken zu lassen.'),
  ('TRX Side Plank', 'core', 'suspension', 'On one forearm, feet stacked in the cradles. Lift the hips in a straight line and hold. Switch sides halfway.', 'Gainage latéral TRX', 'TRX-Seitstütz', 'Sur un avant-bras, pieds l''un sur l''autre dans les sangles. Monter les hanches dans l''alignement et tenir. Changer de côté à mi-temps.', 'Auf einem Unterarm, Füße übereinander in den Schlaufen. Hüfte in eine Linie heben und halten. Zur Hälfte Seite wechseln.'),
  ('TRX Biceps Curl', 'arms', 'suspension', 'Facing the anchor, palms up, lean back with straight arms. Curl the hands to the forehead, elbows high, lower slowly.', 'Curl biceps TRX', 'TRX-Bizepscurl', 'Face à l''ancrage, paumes vers le haut, se pencher en arrière bras tendus. Fléchir les bras pour amener les mains au front, coudes hauts, redescendre lentement.', 'Zum Ankerpunkt gewandt, Handflächen nach oben, mit gestreckten Armen zurücklehnen. Hände zur Stirn beugen, Ellbogen hoch, langsam ablassen.'),
  ('TRX Triceps Extension', 'arms', 'suspension', 'Facing away, arms straight overhead on the handles. Lean forward bending only the elbows, then push back to straight arms.', 'Extension triceps TRX', 'TRX-Trizepsstrecken', 'Dos à l''ancrage, bras tendus au-dessus de la tête sur les poignées. Se pencher en avant en pliant seulement les coudes, puis repousser bras tendus.', 'Vom Ankerpunkt abgewandt, Arme gestreckt über dem Kopf an den Griffen. Nur durch Beugen der Ellbogen nach vorn lehnen, dann zurück zu gestreckten Armen drücken.'),
  ('TRX Y-Fly', 'shoulders', 'suspension', 'Facing the anchor, lean back with straight arms. Raise the arms in a Y above the head, squeezing the shoulder blades, lower slowly.', 'Élévation en Y TRX', 'TRX-Y-Heben', 'Face à l''ancrage, se pencher en arrière bras tendus. Monter les bras en Y au-dessus de la tête en serrant les omoplates, redescendre lentement.', 'Zum Ankerpunkt gewandt, mit gestreckten Armen zurücklehnen. Arme in einem Y über den Kopf heben, Schulterblätter zusammen, langsam ablassen.'),
  ('TRX Jump Squat', 'legs', 'suspension', 'Facing the anchor, holding the handles. Squat down, jump up, land softly back in the squat.', 'Squat sauté TRX', 'TRX-Sprungkniebeuge', 'Face à l''ancrage, poignées en main. Descendre en squat, sauter, se réceptionner en douceur dans le squat.', 'Zum Ankerpunkt gewandt, Griffe halten. In die Kniebeuge gehen, hochspringen, weich in der Kniebeuge landen.'),
  ('TRX Atomic Push-up', 'chest', 'suspension', 'Feet in the cradles, hands on the floor. Do a push-up, then pull the knees to the chest, extend back.', 'Pompe atomique TRX', 'TRX-Atomic-Liegestütz', 'Pieds dans les sangles, mains au sol. Faire une pompe, puis ramener les genoux vers la poitrine, et revenir.', 'Füße in den Schlaufen, Hände am Boden. Einen Liegestütz machen, dann die Knie zur Brust ziehen und zurück.'),
  ('TRX Single-Leg Squat', 'legs', 'suspension', 'Facing the anchor, holding the handles, on one leg, the other forward. Squat down on the standing leg and stand up. Switch legs halfway.', 'Squat sur une jambe TRX', 'Einbeinige TRX-Kniebeuge', 'Face à l''ancrage, poignées en main, sur une jambe, l''autre tendue devant. Descendre sur la jambe d''appui et remonter. Changer de jambe à mi-temps.', 'Zum Ankerpunkt gewandt, Griffe halten, auf einem Bein, das andere nach vorn. Auf dem Standbein beugen und aufstehen. Zur Hälfte Bein wechseln.'),
  ('TRX Sprinter Start', 'legs', 'suspension', 'Facing away, leaning forward on the handles in a sprinter stance. Drive one knee up fast and back down. Switch legs halfway.', 'Départ de sprinteur TRX', 'TRX-Sprinterstart', 'Dos à l''ancrage, penché en avant sur les poignées comme au départ d''un sprint. Monter un genou vite puis le redescendre. Changer de jambe à mi-temps.', 'Vom Ankerpunkt abgewandt, in Sprinterhaltung nach vorn auf die Griffe gelehnt. Ein Knie schnell hochziehen und absetzen. Zur Hälfte Bein wechseln.')
) AS v(name, muscle_group, equipment, description, name_fr, name_de, description_fr, description_de)
WHERE NOT EXISTS (SELECT 1 FROM exercises e WHERE e.user_id IS NULL AND e.name = v.name);

INSERT INTO program_templates (name, description, goal, level, days_per_week, home_friendly, structure, is_published, sort_order, locale)
SELECT 'TRX débutant', 'Trois séances complètes avec seulement des sangles de suspension, à accrocher à une porte ou une barre. Plus on se penche, plus c''est dur : réglez l''inclinaison à chaque série.', 'general', 'beginner', 3, true, '[{"name":"Corps complet A","exercises":[{"exerciseName":"TRX Row","targetSets":3,"targetReps":"10-12","restSec":60},{"exerciseName":"TRX Chest Press","targetSets":3,"targetReps":"8-12","restSec":60},{"exerciseName":"TRX Squat","targetSets":3,"targetReps":"12-15","restSec":60},{"exerciseName":"TRX Hamstring Curl","targetSets":3,"targetReps":"10-12","restSec":60},{"exerciseName":"TRX Plank","targetSets":3,"targetReps":"20-30s","restSec":45}]},{"name":"Corps complet B","exercises":[{"exerciseName":"TRX Row","targetSets":3,"targetReps":"10-12","restSec":60},{"exerciseName":"TRX Biceps Curl","targetSets":3,"targetReps":"10-12","restSec":45},{"exerciseName":"TRX Triceps Extension","targetSets":3,"targetReps":"10-12","restSec":45},{"exerciseName":"TRX Suspended Lunge","targetSets":3,"targetReps":"8-10","restSec":60},{"exerciseName":"TRX Knee Tuck","targetSets":3,"targetReps":"8-10","restSec":45}]},{"name":"Corps complet C","exercises":[{"exerciseName":"TRX Y-Fly","targetSets":3,"targetReps":"10-12","restSec":45},{"exerciseName":"TRX Chest Press","targetSets":3,"targetReps":"8-12","restSec":60},{"exerciseName":"TRX Squat","targetSets":3,"targetReps":"12-15","restSec":60},{"exerciseName":"TRX Hamstring Curl","targetSets":3,"targetReps":"10-12","restSec":60},{"exerciseName":"TRX Side Plank","targetSets":3,"targetReps":"20s","restSec":45}]}]'::jsonb, true, 380, 'fr'
WHERE NOT EXISTS (SELECT 1 FROM program_templates WHERE name = 'TRX débutant' AND locale = 'fr');

INSERT INTO program_templates (name, description, goal, level, days_per_week, home_friendly, structure, is_published, sort_order, locale)
SELECT 'TRX intermédiaire', 'Quatre séances haut et bas du corps aux sangles de suspension, dont un circuit cardio. Pour qui maîtrise déjà le tirage et le développé TRX.', 'hypertrophy', 'intermediate', 4, true, '[{"name":"Haut du corps","exercises":[{"exerciseName":"TRX Row","targetSets":4,"targetReps":"10-12","restSec":60},{"exerciseName":"TRX Chest Press","targetSets":4,"targetReps":"10-12","restSec":60},{"exerciseName":"TRX Y-Fly","targetSets":3,"targetReps":"12","restSec":45},{"exerciseName":"TRX Biceps Curl","targetSets":3,"targetReps":"12","restSec":45},{"exerciseName":"TRX Triceps Extension","targetSets":3,"targetReps":"12","restSec":45}]},{"name":"Bas du corps","exercises":[{"exerciseName":"TRX Single-Leg Squat","targetSets":4,"targetReps":"8","restSec":75},{"exerciseName":"TRX Suspended Lunge","targetSets":3,"targetReps":"10","restSec":60},{"exerciseName":"TRX Hamstring Curl","targetSets":4,"targetReps":"12","restSec":60},{"exerciseName":"TRX Jump Squat","targetSets":3,"targetReps":"10","restSec":60},{"exerciseName":"TRX Pike","targetSets":3,"targetReps":"8-10","restSec":45}]},{"name":"Haut du corps et gainage","exercises":[{"exerciseName":"TRX Atomic Push-up","targetSets":4,"targetReps":"8-10","restSec":60},{"exerciseName":"TRX Row","targetSets":4,"targetReps":"12-15","restSec":60},{"exerciseName":"TRX Y-Fly","targetSets":3,"targetReps":"12","restSec":45},{"exerciseName":"TRX Biceps Curl","targetSets":3,"targetReps":"12","restSec":45},{"exerciseName":"TRX Side Plank","targetSets":3,"targetReps":"30s","restSec":45}]},{"name":"Circuit jambes et cardio","exercises":[{"exerciseName":"TRX Squat","targetSets":3,"targetReps":"15","restSec":30,"supersetWithNext":true},{"exerciseName":"TRX Sprinter Start","targetSets":3,"targetReps":"20","restSec":30,"supersetWithNext":true},{"exerciseName":"TRX Hamstring Curl","targetSets":3,"targetReps":"12","restSec":30,"supersetWithNext":true},{"exerciseName":"TRX Mountain Climber","targetSets":3,"targetReps":"30s","restSec":30,"supersetWithNext":true},{"exerciseName":"TRX Knee Tuck","targetSets":3,"targetReps":"12","restSec":60}]}]'::jsonb, true, 385, 'fr'
WHERE NOT EXISTS (SELECT 1 FROM program_templates WHERE name = 'TRX intermédiaire' AND locale = 'fr');

INSERT INTO program_templates (name, description, goal, level, days_per_week, home_friendly, structure, is_published, sort_order, locale)
SELECT 'TRX for beginners', 'Three full-body sessions with nothing but suspension straps, hung from a door or a bar. The more you lean, the harder it gets: set the angle for each set.', 'general', 'beginner', 3, true, '[{"name":"Full body A","exercises":[{"exerciseName":"TRX Row","targetSets":3,"targetReps":"10-12","restSec":60},{"exerciseName":"TRX Chest Press","targetSets":3,"targetReps":"8-12","restSec":60},{"exerciseName":"TRX Squat","targetSets":3,"targetReps":"12-15","restSec":60},{"exerciseName":"TRX Hamstring Curl","targetSets":3,"targetReps":"10-12","restSec":60},{"exerciseName":"TRX Plank","targetSets":3,"targetReps":"20-30s","restSec":45}]},{"name":"Full body B","exercises":[{"exerciseName":"TRX Row","targetSets":3,"targetReps":"10-12","restSec":60},{"exerciseName":"TRX Biceps Curl","targetSets":3,"targetReps":"10-12","restSec":45},{"exerciseName":"TRX Triceps Extension","targetSets":3,"targetReps":"10-12","restSec":45},{"exerciseName":"TRX Suspended Lunge","targetSets":3,"targetReps":"8-10","restSec":60},{"exerciseName":"TRX Knee Tuck","targetSets":3,"targetReps":"8-10","restSec":45}]},{"name":"Full body C","exercises":[{"exerciseName":"TRX Y-Fly","targetSets":3,"targetReps":"10-12","restSec":45},{"exerciseName":"TRX Chest Press","targetSets":3,"targetReps":"8-12","restSec":60},{"exerciseName":"TRX Squat","targetSets":3,"targetReps":"12-15","restSec":60},{"exerciseName":"TRX Hamstring Curl","targetSets":3,"targetReps":"10-12","restSec":60},{"exerciseName":"TRX Side Plank","targetSets":3,"targetReps":"20s","restSec":45}]}]'::jsonb, true, 380, 'en'
WHERE NOT EXISTS (SELECT 1 FROM program_templates WHERE name = 'TRX for beginners' AND locale = 'en');

INSERT INTO program_templates (name, description, goal, level, days_per_week, home_friendly, structure, is_published, sort_order, locale)
SELECT 'Intermediate TRX', 'Four upper- and lower-body sessions with suspension straps, including a cardio circuit. For those who already master the TRX row and chest press.', 'hypertrophy', 'intermediate', 4, true, '[{"name":"Upper body","exercises":[{"exerciseName":"TRX Row","targetSets":4,"targetReps":"10-12","restSec":60},{"exerciseName":"TRX Chest Press","targetSets":4,"targetReps":"10-12","restSec":60},{"exerciseName":"TRX Y-Fly","targetSets":3,"targetReps":"12","restSec":45},{"exerciseName":"TRX Biceps Curl","targetSets":3,"targetReps":"12","restSec":45},{"exerciseName":"TRX Triceps Extension","targetSets":3,"targetReps":"12","restSec":45}]},{"name":"Lower body","exercises":[{"exerciseName":"TRX Single-Leg Squat","targetSets":4,"targetReps":"8","restSec":75},{"exerciseName":"TRX Suspended Lunge","targetSets":3,"targetReps":"10","restSec":60},{"exerciseName":"TRX Hamstring Curl","targetSets":4,"targetReps":"12","restSec":60},{"exerciseName":"TRX Jump Squat","targetSets":3,"targetReps":"10","restSec":60},{"exerciseName":"TRX Pike","targetSets":3,"targetReps":"8-10","restSec":45}]},{"name":"Upper body and core","exercises":[{"exerciseName":"TRX Atomic Push-up","targetSets":4,"targetReps":"8-10","restSec":60},{"exerciseName":"TRX Row","targetSets":4,"targetReps":"12-15","restSec":60},{"exerciseName":"TRX Y-Fly","targetSets":3,"targetReps":"12","restSec":45},{"exerciseName":"TRX Biceps Curl","targetSets":3,"targetReps":"12","restSec":45},{"exerciseName":"TRX Side Plank","targetSets":3,"targetReps":"30s","restSec":45}]},{"name":"Legs and cardio circuit","exercises":[{"exerciseName":"TRX Squat","targetSets":3,"targetReps":"15","restSec":30,"supersetWithNext":true},{"exerciseName":"TRX Sprinter Start","targetSets":3,"targetReps":"20","restSec":30,"supersetWithNext":true},{"exerciseName":"TRX Hamstring Curl","targetSets":3,"targetReps":"12","restSec":30,"supersetWithNext":true},{"exerciseName":"TRX Mountain Climber","targetSets":3,"targetReps":"30s","restSec":30,"supersetWithNext":true},{"exerciseName":"TRX Knee Tuck","targetSets":3,"targetReps":"12","restSec":60}]}]'::jsonb, true, 385, 'en'
WHERE NOT EXISTS (SELECT 1 FROM program_templates WHERE name = 'Intermediate TRX' AND locale = 'en');

INSERT INTO program_templates (name, description, goal, level, days_per_week, home_friendly, structure, is_published, sort_order, locale)
SELECT 'TRX für Einsteiger', 'Drei Ganzkörpereinheiten nur mit dem Schlingentrainer, an einer Tür oder Stange befestigt. Je schräger du stehst, desto schwerer wird es: Stelle den Winkel für jeden Satz ein.', 'general', 'beginner', 3, true, '[{"name":"Ganzkörper A","exercises":[{"exerciseName":"TRX Row","targetSets":3,"targetReps":"10-12","restSec":60},{"exerciseName":"TRX Chest Press","targetSets":3,"targetReps":"8-12","restSec":60},{"exerciseName":"TRX Squat","targetSets":3,"targetReps":"12-15","restSec":60},{"exerciseName":"TRX Hamstring Curl","targetSets":3,"targetReps":"10-12","restSec":60},{"exerciseName":"TRX Plank","targetSets":3,"targetReps":"20-30s","restSec":45}]},{"name":"Ganzkörper B","exercises":[{"exerciseName":"TRX Row","targetSets":3,"targetReps":"10-12","restSec":60},{"exerciseName":"TRX Biceps Curl","targetSets":3,"targetReps":"10-12","restSec":45},{"exerciseName":"TRX Triceps Extension","targetSets":3,"targetReps":"10-12","restSec":45},{"exerciseName":"TRX Suspended Lunge","targetSets":3,"targetReps":"8-10","restSec":60},{"exerciseName":"TRX Knee Tuck","targetSets":3,"targetReps":"8-10","restSec":45}]},{"name":"Ganzkörper C","exercises":[{"exerciseName":"TRX Y-Fly","targetSets":3,"targetReps":"10-12","restSec":45},{"exerciseName":"TRX Chest Press","targetSets":3,"targetReps":"8-12","restSec":60},{"exerciseName":"TRX Squat","targetSets":3,"targetReps":"12-15","restSec":60},{"exerciseName":"TRX Hamstring Curl","targetSets":3,"targetReps":"10-12","restSec":60},{"exerciseName":"TRX Side Plank","targetSets":3,"targetReps":"20s","restSec":45}]}]'::jsonb, true, 380, 'de'
WHERE NOT EXISTS (SELECT 1 FROM program_templates WHERE name = 'TRX für Einsteiger' AND locale = 'de');

INSERT INTO program_templates (name, description, goal, level, days_per_week, home_friendly, structure, is_published, sort_order, locale)
SELECT 'TRX für Fortgeschrittene', 'Vier Einheiten für Ober- und Unterkörper am Schlingentrainer, darunter ein Cardio-Zirkel. Für alle, die TRX-Rudern und -Brustpresse schon beherrschen.', 'hypertrophy', 'intermediate', 4, true, '[{"name":"Oberkörper","exercises":[{"exerciseName":"TRX Row","targetSets":4,"targetReps":"10-12","restSec":60},{"exerciseName":"TRX Chest Press","targetSets":4,"targetReps":"10-12","restSec":60},{"exerciseName":"TRX Y-Fly","targetSets":3,"targetReps":"12","restSec":45},{"exerciseName":"TRX Biceps Curl","targetSets":3,"targetReps":"12","restSec":45},{"exerciseName":"TRX Triceps Extension","targetSets":3,"targetReps":"12","restSec":45}]},{"name":"Unterkörper","exercises":[{"exerciseName":"TRX Single-Leg Squat","targetSets":4,"targetReps":"8","restSec":75},{"exerciseName":"TRX Suspended Lunge","targetSets":3,"targetReps":"10","restSec":60},{"exerciseName":"TRX Hamstring Curl","targetSets":4,"targetReps":"12","restSec":60},{"exerciseName":"TRX Jump Squat","targetSets":3,"targetReps":"10","restSec":60},{"exerciseName":"TRX Pike","targetSets":3,"targetReps":"8-10","restSec":45}]},{"name":"Oberkörper und Rumpf","exercises":[{"exerciseName":"TRX Atomic Push-up","targetSets":4,"targetReps":"8-10","restSec":60},{"exerciseName":"TRX Row","targetSets":4,"targetReps":"12-15","restSec":60},{"exerciseName":"TRX Y-Fly","targetSets":3,"targetReps":"12","restSec":45},{"exerciseName":"TRX Biceps Curl","targetSets":3,"targetReps":"12","restSec":45},{"exerciseName":"TRX Side Plank","targetSets":3,"targetReps":"30s","restSec":45}]},{"name":"Zirkel Beine und Cardio","exercises":[{"exerciseName":"TRX Squat","targetSets":3,"targetReps":"15","restSec":30,"supersetWithNext":true},{"exerciseName":"TRX Sprinter Start","targetSets":3,"targetReps":"20","restSec":30,"supersetWithNext":true},{"exerciseName":"TRX Hamstring Curl","targetSets":3,"targetReps":"12","restSec":30,"supersetWithNext":true},{"exerciseName":"TRX Mountain Climber","targetSets":3,"targetReps":"30s","restSec":30,"supersetWithNext":true},{"exerciseName":"TRX Knee Tuck","targetSets":3,"targetReps":"12","restSec":60}]}]'::jsonb, true, 385, 'de'
WHERE NOT EXISTS (SELECT 1 FROM program_templates WHERE name = 'TRX für Fortgeschrittene' AND locale = 'de');

COMMIT;
